sp_widget.css:
$bg-main: #06111f;
$bg-panel: #0d1b2f;
$bg-card: rgba(13, 27, 47, 0.72);
$surface: #ffffff;
$surface-soft: #f5f8fc;
$border: #d7e1ef;
$border-strong: #86b8ff;
$text-dark: #172033;
$text-muted: #62718b;
$text-light: #d9e7ff;
$primary: #1f6fff;
$primary-dark: #0f4fca;
$success: #1ea672;
$shadow-lg: 0 24px 60px rgba(5, 17, 34, 0.24);
$shadow-md: 0 10px 30px rgba(15, 42, 84, 0.12);
$radius-xl: 24px;
$radius-lg: 18px;
$radius-md: 14px;
$radius-sm: 10px;

.vg-register {
  min-height: 100vh;
  padding: 32px;
  background:
    radial-gradient(circle at top left, rgba(31, 111, 255, 0.22), transparent 28%),
    linear-gradient(135deg, #08111d 0%, #0b1830 48%, #11284a 100%);
  font-family: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  color: $text-dark;
  box-sizing: border-box;

  * {
    box-sizing: border-box;
  }

  a {
    color: $primary;
    text-decoration: none;
  }
}

.vg-register__shell {
  max-width: 1440px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 300px 1fr;
  background: $surface;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: $radius-xl;
  overflow: hidden;
  box-shadow: $shadow-lg;
}

.vg-register__sidebar {
  padding: 36px 28px;
  background:
    radial-gradient(circle at 20% 20%, rgba(43, 112, 255, 0.22), transparent 22%),
    linear-gradient(180deg, #101d34 0%, #132746 100%);
  color: $text-light;
  display: flex;
  flex-direction: column;
  min-height: 100%;
}

.vg-brand {
  margin-bottom: 40px;

  h1 {
    margin: 18px 0 8px;
    font-size: 34px;
    line-height: 1.1;
    font-weight: 700;
    color: #fff;
  }

  span {
    color: #5aa2ff;
  }

  p {
    margin: 0;
    color: rgba(217, 231, 255, 0.8);
    font-size: 15px;
  }
}

.vg-brand__logo {
  width: 74px;
  height: 74px;
  border-radius: 20px;
  display: grid;
  place-items: center;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.14), rgba(255, 255, 255, 0.04));
  border: 1px solid rgba(255, 255, 255, 0.18);
}

.vg-brand__shield {
  width: 34px;
  height: 40px;
  display: inline-block;
  background: linear-gradient(180deg, #9bc1ff, #2c7dff);
  clip-path: polygon(50% 0%, 95% 18%, 86% 84%, 50% 100%, 14% 84%, 5% 18%);
}

.vg-sidebar-steps {
  display: flex;
  flex-direction: column;
  gap: 22px;
  margin-bottom: 32px;
}

.vg-sidebar-step {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  position: relative;

  strong {
    display: block;
    font-size: 16px;
    color: #fff;
    margin-bottom: 4px;
  }

  small {
    color: rgba(217, 231, 255, 0.78);
    font-size: 14px;
  }

  &.is-active .vg-sidebar-step__count {
    background: linear-gradient(180deg, #2e84ff, #1f6fff);
    border-color: transparent;
    color: #fff;
    box-shadow: 0 8px 18px rgba(31, 111, 255, 0.4);
  }
}

.vg-sidebar-step__count {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-weight: 700;
  color: #d7e7ff;
  border: 1px solid rgba(215, 231, 255, 0.28);
  background: rgba(255, 255, 255, 0.05);
  flex-shrink: 0;
}

.vg-sidebar-card {
  margin-top: auto;
  padding: 20px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(215, 231, 255, 0.1);
  border-radius: $radius-md;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);

  strong {
    display: block;
    margin-bottom: 8px;
    color: #fff;
    font-size: 16px;
  }

  p {
    margin: 0;
    color: rgba(217, 231, 255, 0.8);
    font-size: 14px;
    line-height: 1.6;
  }
}

.vg-sidebar-login {
  padding-top: 28px;
  text-align: center;

  p {
    margin: 0 0 8px;
    color: rgba(217, 231, 255, 0.76);
  }

  a {
    font-weight: 600;
  }
}

.vg-register__content {
  background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
}

.vg-register__header {
  padding: 34px 36px 24px;
  border-bottom: 1px solid #ebf1f8;
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: flex-start;

  h2 {
    margin: 0 0 6px;
    font-size: 36px;
    line-height: 1.15;
    font-weight: 700;
    color: #16233a;
  }

  p {
    margin: 0;
    color: $text-muted;
    font-size: 16px;
  }
}

.vg-top-steps {
  display: flex;
  align-items: center;
  gap: 18px;
}

.vg-top-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  color: $text-muted;
  font-size: 13px;
  font-weight: 600;
  min-width: 90px;

  span {
    width: 38px;
    height: 38px;
    border-radius: 999px;
    display: grid;
    place-items: center;
    border: 1px solid $border;
    background: #fff;
  }

  &.is-active {
    color: $primary;

    span {
      color: #fff;
      border-color: $primary;
      background: linear-gradient(180deg, #2f83ff, #1f6fff);
      box-shadow: 0 10px 18px rgba(31, 111, 255, 0.22);
    }
  }
}

.vg-form {
  padding: 24px 20px 30px;
}

.vg-card {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 28px;
  padding: 28px;
  margin-bottom: 18px;
  border: 1px solid #e8eef6;
  border-radius: $radius-lg;
  background: #fff;
  box-shadow: $shadow-md;
}

.vg-card__intro {
  h3 {
    margin: 0 0 8px;
    font-size: 28px;
    line-height: 1.2;
    color: #16233a;
  }

  p {
    margin: 0;
    color: $text-muted;
    font-size: 15px;
    line-height: 1.6;
  }
}

.vg-role-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}

.vg-role-option {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 22px 18px;
  border: 1px solid $border;
  border-radius: $radius-md;
  background: linear-gradient(180deg, #ffffff, #f9fbff);
  cursor: pointer;
  transition: 0.2s ease;

  input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
  }

  &:hover {
    border-color: #abcfff;
    transform: translateY(-1px);
  }

  &.is-selected {
    border-color: $border-strong;
    box-shadow: 0 0 0 3px rgba(31, 111, 255, 0.12);
    background: linear-gradient(180deg, #fafdff, #f1f7ff);
  }
}

.vg-role-option__icon {
  width: 52px;
  height: 52px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  font-size: 24px;
  background: #edf4ff;
  color: $primary;
  flex-shrink: 0;
}

.vg-role-option__body {
  strong {
    display: block;
    margin-bottom: 6px;
    font-size: 18px;
    color: #16233a;
  }

  p {
    margin: 0;
    font-size: 14px;
    line-height: 1.65;
    color: $text-muted;
  }
}

.vg-form-grid {
  display: grid;
  gap: 18px;
  width: 100%;

  &.vg-form-grid--3 {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  &.vg-form-grid--2 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.vg-field {
  label {
    display: block;
    margin-bottom: 8px;
    font-size: 14px;
    font-weight: 600;
    color: #23314b;
  }

  input,
  select,
  textarea {
    width: 100%;
    height: 48px;
    padding: 0 16px;
    border: 1px solid $border;
    border-radius: $radius-sm;
    background: #fff;
    color: $text-dark;
    font-size: 14px;
    outline: 0;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;

    &::placeholder {
      color: #93a0b4;
    }

    &:focus {
      border-color: $primary;
      box-shadow: 0 0 0 3px rgba(31, 111, 255, 0.12);
    }
  }
}

.vg-password-hint {
  margin-top: 16px;
  color: $success;
  font-size: 14px;
  line-height: 1.6;
}

.vg-role-sections {
  width: 100%;
}

.vg-role-panel {
  padding: 22px;
  border: 1px solid #e8eef6;
  border-radius: $radius-md;
  background: linear-gradient(180deg, #ffffff, #fbfdff);

  h4 {
    margin: 0 0 18px;
    font-size: 18px;
    color: #16233a;
  }
}

.vg-form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 24px;
}

.vg-btn {
  min-width: 140px;
  height: 48px;
  padding: 0 22px;
  border-radius: 12px;
  border: 0;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition: 0.2s ease;

  &.vg-btn--ghost {
    background: transparent;
    color: $primary;
    border: 1px solid #cfe0ff;

    &:hover {
      background: #f4f8ff;
    }
  }

  &.vg-btn--primary {
    color: #fff;
    background: linear-gradient(180deg, #2b80ff, #1f6fff);
    box-shadow: 0 14px 24px rgba(31, 111, 255, 0.24);

    &:hover {
      background: linear-gradient(180deg, #2374ec, #165edb);
    }
  }
}

.vg-form-footer {
  margin-top: 18px;
  text-align: center;
  color: $text-muted;
  font-size: 14px;
  line-height: 1.6;
}

@media (max-width: 1200px) {
  .vg-register__shell {
    grid-template-columns: 1fr;
  }

  .vg-register__sidebar {
    padding: 28px;
  }

  .vg-register__header,
  .vg-card {
    grid-template-columns: 1fr;
  }

  .vg-role-grid,
  .vg-form-grid.vg-form-grid--3 {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 768px) {
  .vg-register {
    padding: 16px;
  }

  .vg-register__header {
    padding: 24px 20px 20px;
    flex-direction: column;

    h2 {
      font-size: 28px;
    }
  }

  .vg-form {
    padding: 18px 14px 24px;
  }

  .vg-card {
    padding: 20px;
    gap: 20px;
  }

  .vg-role-grid,
  .vg-form-grid.vg-form-grid--3,
  .vg-form-grid.vg-form-grid--2 {
    grid-template-columns: 1fr;
  }

  .vg-form-actions {
    flex-direction: column;
  }

  .vg-btn {
    width: 100%;
  }
}
